      { q: "‘सहनशीलता के आगर’ का आशय है –", options: ["कम सहने वाले", "बहुत क्रोधी", "सहनशीलता के भंडार", "भयभीत"], answer: 2, explain: "‘आगर’ का अर्थ खज़ाना या भंडार है।", level: 2 },
      { q: "‘श्रम सागर तरते हैं’ में कौन-सा अलंकार है?", options: ["उपमा", "अनुप्रास", "यमक", "रूपक"], answer: 3, explain: "श्रम को सागर कहा गया है, इसलिए रूपक अलंकार है।", level: 2 },
      { q: "‘मीन-मेख करके बुध वाद कठोर किया करें’ से किन पर व्यंग्य है?", options: ["दोष निकालने वाले विद्वानों पर", "किसानों पर", "सैनिकों पर", "बच्चों पर"], answer: 0, explain: "व्यर्थ तर्क-वितर्क करने वाले विद्वान इसके लक्ष्य हैं।", level: 2 },
      { q: "किसान निडर हैं, क्योंकि –", options: ["उनके पास हथियार हैं", "उनके पास महल हैं", "वे दूसरों से दूर रहते हैं", "उनके रक्षक राजा-जैसे लोग हैं"], answer: 3, explain: "कविता में कहा है कि हम-जैसे प्रहरी जिनके रक्षक हों, वे किससे डरेंगे।", level: 2 },
      { q: "गाँव के एक बुज़ुर्ग किसान अकाल में भी संतोष से परिश्रम करते हैं और पर्व मनाते हैं। उनका जीवन कविता के किस भाव से मेल खाता है?", options: ["अभिमान और लालच", "सादगी, परिश्रम और संतोष", "कलह और ईर्ष्या", "भय और निराशा"], answer: 1, explain: "किसानों का सहनशील, श्रमशील और संतुष्ट जीवन कविता का मुख्य भाव है।", level: 3 },
      { q: "‘हम राज्य लिए मरते हैं’ की पुनरावृत्ति का क्या प्रभाव है?", options: ["केवल छंद पूरा करना", "भाषा को कठिन बनाना", "राज्य-लोभ के दुख पर बार-बार बल देना", "किसानों का अपमान"], answer: 2, explain: "यह टेक राज्य-लालसा से उत्पन्न व्यर्थ पीड़ा को उभारती है।", level: 3 },
      { q: "गुप्त जी की कविता में नारी का कैसा रूप मिलता है?", options: ["केवल अबला", "केवल गृहिणी", "केवल भक्त", "स्वाभिमानिनी और लोकसेविका"], answer: 3, explain: "उन्होंने नारी को अबला से ऊपर उठाकर स्वाभिमानी और लोकसेविका के रूप में दिखाया।", level: 3 }
