      { q: "ममता ने हुमायूँ को आश्रय देकर किस आदर्श का पालन किया?", options: ["जैसे को तैसा", "धन-संग्रह", "अतिथि देवो भव", "शत्रु से बदला"], answer: 2, explain: "अतिथि को देवता मानने का भारतीय आदर्श।", level: 2 },
      { q: "शिलालेख में ममता का नाम न होना क्या दर्शाता है?", options: ["उपेक्षा", "इतिहास की भूल", "लेखक की भूल", "निस्वार्थ सेवा का प्रतिफल नहीं चाहना"], answer: 3, explain: "परोपकार में नाम की चाह नहीं – ममता के त्याग का संकेत।", level: 3 },
      { q: "ममता का हुमायूँ के सामने न आना किस मनःस्थिति का संकेत है?", options: ["भय और पिता की घटना की पीड़ा", "लोभ", "घमंड", "अज्ञान"], answer: 0, explain: "वह डर के कारण छिपी रही; पिता की मृत्यु और अपनी असुरक्षा उसके मन में थी।", level: 3 },
      { q: "रानी अपने राज्य में आए एक भूखे अजनबी को भोजन देती है, चाहे वह शत्रु-पक्ष का हो। यह किस पात्र की प्रवृत्ति से मेल खाता है?", options: ["चूड़ामणि", "शेरशाह", "ममता", "अकबर"], answer: 2, explain: "ममता ने भी शत्रु-पक्ष के हुमायूँ को आश्रय दिया।", level: 3 },
      { q: "‘चौसा का युद्ध’ किनके बीच हुआ?", options: ["बाबर और राणा साँगा", "अकबर और हेमू", "हुमायूँ और शेरशाह", "शेरशाह और अकबर"], answer: 2, explain: "1539 में चौसा में हुमायूँ और शेरशाह की सेनाएँ लड़ीं।", level: 2 }
