      { q: "मनोहर सिंह ने पेड़ क्यों गिरवी रखा था?", a: "अभाव (आर्थिक तंगी) के कारण उसे पेड़ ज़मींदार के पास गिरवी रखना पड़ा।", marks: 1 },
      { q: "मनोहर सिंह का नीम के पेड़ से लगाव किस प्रकार प्रकट होता है?", a: "1. पेड़ उसके पिता ने लगाया था, इसलिए वह उसकी निशानी था।\n2. वह उसे कटने से बचाने के लिए जान देने को तैयार था।\n3. अंत में उसने उसे योग्य उत्तराधिकारी तेजा को सौंप दिया।", marks: 3 },
      { q: "तेजा सिंह के गुण लिखिए।", a: "1. वह संवेदनशील है और मनोहर की भावना की कद्र करता है।\n2. साहसी है और पेड़ बचाने के लिए प्रयत्न करता है।\n3. परोपकारी और प्रकृति-प्रेमी है।", marks: 3 },
      { q: "ज़मींदार का चरित्र कैसा है? संक्षेप में लिखिए।", a: "1. वह स्वार्थी है और भावना की जगह लाभ देखता है।\n2. पेड़ गिरवी रखकर उसे कटवाना चाहता है।\n3. गरीब किसान की भावनाओं की उसे परवाह नहीं।", marks: 3 },
      { q: "मनोहर सिंह का चरित्र-चित्रण कीजिए।", a: "1. मनोहर साधारण और अशिक्षित ग्रामीण है।\n2. वह भावुक और पिता का सम्मान करने वाला पुत्र है।\n3. प्रकृति से उसका गहरा आत्मीय लगाव है।\n4. वह स्वाभिमानी और दृढ़ निश्चयी है; जान देकर भी पेड़ बचाना चाहता है।\n5. वह उदार भी है, तभी योग्य बालक को पेड़ सौंप देता है।", marks: 5 },
      { q: "‘अशिक्षित का हृदय’ कहानी का उद्देश्य स्पष्ट कीजिए।", a: "1. कहानी मनुष्य और प्रकृति के भावात्मक संबंध को दर्शाती है।\n2. यह बताती है कि शिक्षा न होने पर भी हृदय संवेदनशील हो सकता है।\n3. पेड़ों की रक्षा और पर्यावरण-संरक्षण का संदेश देती है।\n4. स्वार्थ और भावना के संघर्ष को दिखाती है।\n5. युवा पीढ़ी को परंपरा और विरासत की रक्षा के लिए प्रेरित करती है।", marks: 5 },
      { q: "पढ़िए – गाँव के चौराहे पर एक पुराना पीपल का पेड़ था। सड़क बनाने वाले ठेकेदार उसे काटना चाहते थे। गाँव के बुजुर्ग रामलाल ने पेड़ से लिपटकर कहा कि पहले मुझे काटो। बच्चों ने भी मिलकर पोस्टर लगाए और पेड़ बच गया।\n(i) रामलाल का व्यवहार किस पात्र जैसा है?\n(ii) बच्चों का कार्य किस पात्र की याद दिलाता है?\n(iii) इस घटना से हमें क्या शिक्षा मिलती है?", a: "(i) मनोहर सिंह जैसा।\n(ii) तेजा सिंह की।\n(iii) पेड़ हमारी धरोहर हैं और सामूहिक प्रयास से उनकी रक्षा की जा सकती है।", marks: 4, type: "case" }
