      { q: "इकतीस तारीख को कर्मचारी के घूस लेने का मुख्य कारण क्या है?", options: ["तावीज़ का दोष", "आर्थिक अभाव और असुरक्षा", "राजा की परीक्षा", "लोभ का अभाव"], answer: 1, explain: "लेखक संकेत करता है कि कम वेतन और आर्थिक असुरक्षा भ्रष्टाचार को बढ़ाती है।", level: 3 },
      { q: "साधु को ठेका देने का व्यंग्य क्या दर्शाता है?", options: ["सरकारी कार्यों में ठेकेदारी में भी स्वार्थ और भ्रष्टाचार का आना", "साधु बहुत ईमानदार था", "ठेके अच्छे होते हैं", "तावीज़ सस्ता था"], answer: 0, explain: "तावीज़ के ठेके और पेशगी के रूप में पूरी व्यवस्था पर व्यंग्य है।", level: 3 },
      { q: "इस व्यंग्य का निहितार्थ क्या है?", options: ["बाहरी दिखावटी उपायों से भ्रष्टाचार नहीं मिटता, कारण दूर करने पड़ते हैं", "तावीज़ हर रोग की दवा है", "राजा बहुत बुद्धिमान था", "दरबारी ईमानदार थे"], answer: 0, explain: "लेखक कारणों को दूर करने की सलाह देता है।", level: 3 }
