    written: [
      { q: "धर्मवीर भारती किस पत्रिका के संपादक रहे?", a: "वे साप्ताहिक पत्रिका ‘धर्मयुग’ के प्रधान संपादक रहे।", marks: 1 },
      { q: "‘ठेले पर हिमालय’ शीर्षक किस बात का प्रतीक है?", a: "ठेले पर रखी बरफ़ की सिल हिमालय की याद का प्रतीक है, जिसे देखकर मन बहला लिया जाता है।", marks: 1 },
      { q: "कोसी से कौसानी तक के रास्ते का वर्णन कीजिए।", a: "1. नैनीताल से रानीखेत और फिर कोसी तक का रास्ता सूखा, कठिन और कुरूप था।\n2. कोसी के बाद सोमेश्वर की घाटी हरी-भरी और सुंदर थी।\n3. कौसानी पर्वतमाला की चोटी पर बसा है।", marks: 3 },
      { q: "कत्यूर घाटी का सौंदर्य लेखक ने कैसे चित्रित किया है?", a: "1. पचासों मील चौड़ी घाटी में हरे मखमली खेत थे।\n2. गेरू की शिलाएँ काटकर बने लाल रास्ते और सफ़ेद पत्थरों की कतारें थीं।\n3. बेलों की लड़ियों जैसी नदियाँ उलझी हुई थीं और पूरा दृश्य किन्नर-यक्षों के लोक जैसा लगता था।", marks: 3 },
      { q: "हिम-दर्शन के बाद साथियों की मनःस्थिति कैसी थी?", a: "1. पहले एक क्षण के दर्शन से निराशा-थकावट दूर हो गई।\n2. बादल छँटने पर सब अपलक देखते रहे और चाय तक भूल गए।\n3. सूर्यास्त के बाद सब गुमसुम और आत्मलीन हो गए।", marks: 3 },
      { q: "‘ठेले पर हिमालय’ निबंध का सार लिखिए।", a: "1. बरफ़ के ठेले को देखकर लेखक को शीर्षक सूझा।\n2. वह कौसानी बरफ़ देखने गया; रास्ता कठिन था।\n3. कौसानी पहुँचकर पहले निराशा हुई, फिर घाटी का सौंदर्य देखकर वह स्तब्ध हो गया।\n4. बादल हटने पर हिमालय की श्रृंखला दिखी और सबके मन अभिभूत हो गए।\n5. आज भी उसकी याद टीस देती है, इसलिए लेखक ठेले की बरफ़ से मन बहलाता है।", marks: 5 },
      { q: "इस निबंध में प्रकृति-चित्रण की विशेषताएँ बताइए।", a: "1. चित्रात्मक और आलंकारिक भाषा।\n2. रंगों का सजीव वर्णन (केसरिया, लाल कमल जैसी बरफ़)।\n3. घाटी और हिम-श्रृंखला का जीवंत चित्रण।\n4. लेखक के भावों का प्रकृति से गहरा जुड़ाव।\n5. पर्वतीय स्थलों के प्रति आकर्षण जगाने वाली शैली।", marks: 5 },
      { q: "पढ़िए – पहाड़ी यात्रा के दौरान रीना की बस घंटों रुकी रही। सभी थककर चिड़चिड़े हो गए। तभी बादल हटे और सामने बरफ़ से ढकी चोटियाँ चमकने लगीं। थकान भूलकर सब बाहर निकले और निःशब्द देखते रहे।\n(i) यह घटना निबंध के किस प्रसंग जैसी है?\n(ii) बादलों के हटने से मन पर क्या प्रभाव पड़ा?\n(iii) प्रकृति हमें क्या सिखाती है?", a: "(i) कौसानी में बादलों के बीच से हिमालय के प्रकट होने जैसी।\n(ii) थकान और निराशा मिट गई तथा मन आनंद से भर गया।\n(iii) प्रकृति धैर्य सिखाती है और उसका सौंदर्य मन को शांति और ऊर्जा देता है।", marks: 4, type: "case" }
    ]
